const fn hex(s: &str) -> [u8; 32] {
    assert!(s.len() == 64);
    let mut out = [0; 32];
    let bytes = s.as_bytes();
    let mut i = 0;
    while i < 32 {
        out[i] = (nibble(bytes[2 * i]) << 4) | nibble(bytes[2 * i + 1]);
        i += 1;
    }
    out
}
const fn nibble(c: u8) -> u8 {
    match c {
        b'0'..=b'9' => c - b'0',
        b'a'..=b'f' => c - b'a' + 10,
        _ => panic!("compiled SHA256 literal"),
    }
}
